(function(){
var INK="#26303b",GRAY="#8a949f",FILL="#eceff2";
function n(v){return Math.round(v*10)/10}
function T(x,y,size,txt,cls,anchor){return '<text x="'+n(x)+'" y="'+n(y)+'" font-size="'+size+'"'+(anchor?' text-anchor="'+anchor+'"':'')+(cls?' class="'+cls+'"':'')+'>'+txt+'</text>'}
function TN(x,y,size,txt,cls,anchor){return '<text x="'+n(x)+'" y="'+n(y)+'" font-size="'+size+'" style="stroke:none"'+(anchor?' text-anchor="'+anchor+'"':'')+(cls?' class="'+cls+'"':'')+'>'+txt+'</text>'}
function line(x1,y1,x2,y2,k,w){return '<line x1="'+n(x1)+'" y1="'+n(y1)+'" x2="'+n(x2)+'" y2="'+n(y2)+'" stroke="'+k+'" stroke-width="'+(w||1)+'"/>'}
function svg(h,label,body){return '<div class="fig"><svg viewBox="0 0 340 '+h+'" role="img" aria-label="'+label+'">'+body+'</svg></div>'}
/* 矢印：x1からx2へ(x2が左なら左向き) */
function arrow(x1,x2,y,k){var d=x2>x1?1:-1;k=k||INK;
 return line(x1,y,x2,y,k,1.5)+'<path d="M'+n(x2-d*6)+','+n(y-5)+' L'+n(x2)+','+n(y)+' L'+n(x2-d*6)+','+n(y+5)+'" fill="none" stroke="'+k+'" stroke-width="1.5"/>'}
function ld(x1,y1,x2,y2){return line(x1,y1,x2,y2,INK,1)+'<circle cx="'+n(x2)+'" cy="'+n(y2)+'" r="2.5" fill="'+INK+'"/>'}
function box(id,cx,cy,w,h,fs){
 return '<g class="bl" data-b="'+id+'"><rect x="'+n(cx-w/2)+'" y="'+n(cy-h/2)+'" width="'+w+'" height="'+h+'" rx="4"/>'+
  '<text class="bt" x="'+n(cx)+'" y="'+n(cy+fs*.36)+'" font-size="'+fs+'" text-anchor="middle"></text>'+
  '<text class="bm" x="'+n(cx+w/2-2)+'" y="'+n(cy-h/2+10)+'" font-size="12" text-anchor="end"></text></g>'}

/* ---------- 図1：消化の表。mode＝"point"(全部書く)、"blank"(問題：空欄)、"ans"(解答)。酵素＝青、分解後の物質＝赤 ---------- */
var R=[
 {nm:"デンプン",ls:["だ液","すい液"],es:["アミラーゼ","アミラーゼ"],res:"ブドウ糖",id:["a1","a2","a3"]},
 {nm:"タンパク質",ls:["胃液","すい液"],es:["ペプシン","トリプシン"],res:"アミノ酸",id:["a4","a5","a6"]},
 {nm:"脂肪",ls:["すい液","胆汁"],es:["リパーゼ",""],res:"脂肪酸とモノグリセリド",id:["a7","a8","a9"]}];
/* 列の位置：→は、「タンパク質」の右はし(72)と、「モノグリセリド」の左はし(217)の、まん中(144.5)。消化液(酵素)も、→と中央そろえ */
var XC=144.5,XR=266,XA1=96,XA2=192;
function fig1(mode){
 var b=mode==="blank",P=b?76:64,c0=b?62:56,s=T(XC,14,11,"消化液(酵素)","g","middle")+T(XR,14,11,"分解後","g","middle");
 R.forEach(function(r,i){var cy=c0+P*i;
  s+=T(37,cy+5,14,r.nm,"b","middle")+arrow(XA1,XA2,cy);
  if(b)s+=box(r.id[0],XC,cy-19,64,22,13)+box(r.id[1],XC,cy+19,92,22,13)+box(r.id[2],XR,cy,140,28,12);
  else{
   s+=T(XC,cy-7,11,r.ls[0]+'(<tspan class="v b">'+r.es[0]+'</tspan>)',null,"middle");
   s+=r.es[1]?T(XC,cy+17,11,r.ls[1]+'(<tspan class="v b">'+r.es[1]+'</tspan>)',null,"middle"):T(XC,cy+17,11,"胆汁(酵素なし)","g","middle");
   s+=r.res.length>8?TN(XR,cy-2,14,"脂肪酸と","m b","middle")+TN(XR,cy+16,14,"モノグリセリド","m b","middle"):TN(XR,cy+5,14,r.res,"m b","middle")}});
 return svg(b?252:214,b?
  "消化の表。デンプン、タンパク質、脂肪の3行。各行に、右向きの矢印があり、矢印の上に消化液の空欄、下に消化酵素の空欄、右に分解後の物質の空欄がある。空欄は9つ":
  "消化の表。デンプンは、だ液のアミラーゼとすい液のアミラーゼで、ブドウ糖になる。タンパク質は、胃液のペプシンとすい液のトリプシンで、アミノ酸になる。脂肪は、すい液のリパーゼで、脂肪酸とモノグリセリドになる。胆汁は、酵素をふくまない。酵素は青、分解後の物質は赤",s)}

/* ---------- 図2：柔毛(1本)。ブドウ糖・アミノ酸は毛細血管へ、脂肪酸とモノグリセリドはリンパ管へ ---------- */
var MESH='<defs><linearGradient id="vg" gradientUnits="userSpaceOnUse" x1="141" y1="0" x2="199" y2="0"><stop offset="0" stop-color="#c2410c"/><stop offset=".4" stop-color="#c2410c"/><stop offset=".6" stop-color="#1f5fa8"/><stop offset="1" stop-color="#1f5fa8"/></linearGradient></defs><g fill="none" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M141,200 V62 A29,29 0 0 1 170,33" stroke="#c2410c"/><path d="M170,33 A29,29 0 0 1 199,62 V200" stroke="#1f5fa8"/><g stroke="url(#vg)"><path d="M141.0,62.0 L143.0,62.3 L145.0,63.1 L147.0,64.3 L149.0,65.7 L151.0,66.9 L153.0,67.7 L155.0,68.0 L157.1,67.5 L159.3,65.9 L161.4,63.7 L163.6,61.3 L165.7,59.1 L167.9,57.5 L170.0,57.0 L172.1,57.4 L174.3,58.5 L176.4,60.1 L178.6,61.9 L180.7,63.5 L182.9,64.6 L185.0,65.0 L187.0,64.9 L189.0,64.4 L191.0,63.8 L193.0,63.2 L195.0,62.6 L197.0,62.1 L199.0,62.0"/><path d="M141.0,88.0 L143.0,87.7 L145.0,86.9 L147.0,85.7 L149.0,84.3 L151.0,83.1 L153.0,82.3 L155.0,82.0 L157.1,82.5 L159.3,84.1 L161.4,86.3 L163.6,88.7 L165.7,90.9 L167.9,92.5 L170.0,93.0 L172.1,92.6 L174.3,91.5 L176.4,89.9 L178.6,88.1 L180.7,86.5 L182.9,85.4 L185.0,85.0 L187.0,85.2 L189.0,85.8 L191.0,86.6 L193.0,87.4 L195.0,88.2 L197.0,88.8 L199.0,89.0"/><path d="M141.0,113.0 L143.0,113.3 L145.0,114.1 L147.0,115.3 L149.0,116.7 L151.0,117.9 L153.0,118.7 L155.0,119.0 L157.1,118.5 L159.3,116.9 L161.4,114.7 L163.6,112.3 L165.7,110.1 L167.9,108.5 L170.0,108.0 L172.1,108.4 L174.3,109.5 L176.4,111.1 L178.6,112.9 L180.7,114.5 L182.9,115.6 L185.0,116.0 L187.0,115.8 L189.0,115.2 L191.0,114.4 L193.0,113.6 L195.0,112.8 L197.0,112.2 L199.0,112.0"/><path d="M141.0,139.0 L143.0,138.7 L145.0,137.9 L147.0,136.7 L149.0,135.3 L151.0,134.1 L153.0,133.3 L155.0,133.0 L157.1,133.5 L159.3,135.1 L161.4,137.3 L163.6,139.7 L165.7,141.9 L167.9,143.5 L170.0,144.0 L172.1,143.6 L174.3,142.5 L176.4,140.9 L178.6,139.1 L180.7,137.5 L182.9,136.4 L185.0,136.0 L187.0,136.2 L189.0,136.8 L191.0,137.6 L193.0,138.4 L195.0,139.2 L197.0,139.8 L199.0,140.0"/><path d="M141.0,164.0 L143.0,164.3 L145.0,165.1 L147.0,166.3 L149.0,167.7 L151.0,168.9 L153.0,169.7 L155.0,170.0 L157.1,169.5 L159.3,167.9 L161.4,165.7 L163.6,163.3 L165.7,161.1 L167.9,159.5 L170.0,159.0 L172.1,159.4 L174.3,160.5 L176.4,162.1 L178.6,163.9 L180.7,165.5 L182.9,166.6 L185.0,167.0 L187.0,166.8 L189.0,166.2 L191.0,165.4 L193.0,164.6 L195.0,163.8 L197.0,163.2 L199.0,163.0"/><path d="M141.0,190.0 L143.0,189.7 L145.0,188.9 L147.0,187.7 L149.0,186.3 L151.0,185.1 L153.0,184.3 L155.0,184.0 L157.1,184.4 L159.3,185.7 L161.4,187.5 L163.6,189.5 L165.7,191.3 L167.9,192.6 L170.0,193.0 L172.1,192.7 L174.3,191.7 L176.4,190.3 L178.6,188.7 L180.7,187.3 L182.9,186.3 L185.0,186.0 L187.0,186.2 L189.0,186.8 L191.0,187.6 L193.0,188.4 L195.0,189.2 L197.0,189.8 L199.0,190.0"/><path d="M155.0,68.0 L157.1,68.4 L159.3,69.5 L161.4,71.1 L163.6,72.9 L165.7,74.5 L167.9,75.6 L170.0,76.0 L172.1,76.4 L174.3,77.7 L176.4,79.5 L178.6,81.5 L180.7,83.3 L182.9,84.6 L185.0,85.0"/><path d="M185.0,85.0 L187.3,83.2 L189.7,79.8 L192.0,78.0 L194.3,77.5 L196.7,76.5 L199.0,76.0"/><path d="M155.0,119.0 L157.1,119.3 L159.3,120.1 L161.4,121.3 L163.6,122.7 L165.7,123.9 L167.9,124.7 L170.0,125.0 L172.1,125.5 L174.3,127.1 L176.4,129.3 L178.6,131.7 L180.7,133.9 L182.9,135.5 L185.0,136.0"/><path d="M185.0,136.0 L187.3,139.0 L189.7,145.0 L192.0,148.0 L194.3,148.5 L196.7,149.5 L199.0,150.0"/><path d="M155.0,170.0 L157.1,170.4 L159.3,171.7 L161.4,173.5 L163.6,175.5 L165.7,177.3 L167.9,178.6 L170.0,179.0 L172.1,179.3 L174.3,180.3 L176.4,181.7 L178.6,183.3 L180.7,184.7 L182.9,185.7 L185.0,186.0"/><path d="M185.0,186.0 L187.3,184.0 L189.7,180.0 L192.0,178.0 L194.3,177.8 L196.7,177.2 L199.0,177.0"/></g></g>';
function fig2(){
 var s='<path d="M135,200 V62 A35,35 0 0 1 205,62 V200" fill="#fff" stroke="'+INK+'" stroke-width="1.5"/>'+
  '<path d="M164,198 V72 Q164,62 170,62 Q176,62 176,72 V198" fill="#fbe7b0" stroke="#b7791f" stroke-width="1.5"/>'+
  MESH+
  line(90,200,250,200,GRAY,1)+T(170,216,11,"小腸のかべ","g","middle")+
  T(170,14,14,"柔毛","b","middle")+ld(170,20,170,28)+
  T(4,95,14,"ブドウ糖","b")+T(4,115,14,"アミノ酸","b")+arrow(80,138,100)+
  T(336,95,14,"脂肪酸と","b","end")+T(336,115,14,"モノグリセリド","b","end")+arrow(236,179,100)+
  T(4,161,13,"毛細血管","b")+ld(66,156,141,156)+
  T(336,161,13,"リンパ管","b","end")+ld(272,156,177,156);
 return svg(226,"柔毛の図。小腸のかべから、柔毛が1本のびている。中心にリンパ管が1本ある。柔毛の内側のふちに沿って、左に赤、右に青の毛細血管があり、左から右へ、基本の6本の波線が、分岐や合流をくり返す毛細血管が、リンパ管の手前を通ってつながっている。ブドウ糖とアミノ酸は、毛細血管へ。脂肪酸とモノグリセリドは、リンパ管へ入る",s)}

/* ---------- ノート用の図：書く順番を、3つの段で見せる。今の段は色つき、前の段は薄い灰色。棒は、書く場所の目安(答えは書かない) ---------- */
function bar(x,y,w,h,k){return '<rect x="'+n(x)+'" y="'+n(y)+'" width="'+w+'" height="'+h+'" rx="2" fill="'+k+'"/>'}
function figNote(){
 var TT=["① 栄養素","② 消化液と消化酵素","③ 分解後"],LG="#c9d0d7",BL="#1f5fa8",RD="#c2410c",s='',k,i,y0,cy;
 for(k=0;k<3;k++){y0=k*112;
  if(k)s+=line(4,y0-4,336,y0-4,LG,1);
  s+=T(4,y0+16,13,TT[k],"b");
  for(i=0;i<3;i++){cy=y0+40+28*i;
   s+=bar(9,cy-5,56,10,k===0?INK:LG);
   if(k>=1)s+=arrow(XA1,XA2,cy,k===1?INK:LG)+bar(XC-38,cy-11,76,5,k===1?BL:LG)+bar(XC-38,cy+6,76,5,k===1?BL:LG);
   if(k>=2)s+=bar(XR-52,cy-5,104,10,RD)}}
 return svg(336,"ノート用の図。書く順番を、3つの段で示している。1段目は、栄養素を、左にたてに3つ書く。2段目は、右向きの矢印を書き、矢印の上と下に、消化液と消化酵素を書く。3段目は、矢印の右に、分解後の物質を書く",s)}

/* ---------- 文章 ---------- */
var SM='<p class="note" style="font-size:.8rem;margin:.2rem 0">';
var HD='font-size:1.05rem;font-weight:700;line-height:1.5;margin:1.8rem 0 .3rem;padding-bottom:.2rem;border-bottom:1px solid #c9d0d7';
function hd(x,first){return '<h3 style="'+HD+(first?';margin-top:.9rem':'')+'">'+x+'</h3>'}
var POINT=hd('消化',true)+
 '<p>食べ物の栄養は、消化液にふくまれる<b>消化酵素</b>のはたらきで、吸収できる小さな物質に分解されます。</p>'+fig1("point")+
 SM+'※ 胆汁は、消化酵素をふくみません。脂肪の消化を助けます。</p>'+SM+'※ このほか、腸液もデンプンとタンパク質にはたらきます。</p>'+
 hd('吸収')+
 '<p>分解された物質は、小腸の壁にある<b>柔毛</b>から吸収されます。</p>'+fig2()+
 SM+'※ 脂肪酸とモノグリセリドは、柔毛の中で、脂肪にもどってから、リンパ管に入ります。</p>';

var QBODY='<p>消化の表です。各行の消化液は、だ液・胃液・すい液を、1回ずつ使います。空欄に入る言葉を、下の語群から選びなさい。</p>';
var ANS={a1:"だ液",a2:"アミラーゼ",a3:"ブドウ糖",a4:"胃液",a5:"ペプシン",a6:"アミノ酸",a7:"すい液",a8:"リパーゼ",a9:"脂肪酸とモノグリセリド"};
var CH=["ブドウ糖","トリプシン","すい液","アミノ酸","アミラーゼ","胆汁","だ液","脂肪酸とモノグリセリド","ペプシン","胃液","リパーゼ"];
var ANSW=fig1("ans")+'<p>酵素は、分解する物質ごとに決まっています。</p>';

var SBODY='<p>吸収された物質は、柔毛の中の何に入るか。丸をタップして選びなさい。</p>';
var SOL2=fig2()+'<p>ブドウ糖：<b>毛細血管</b><br>アミノ酸：<b>毛細血管</b><br>脂肪酸など：<b>リンパ管</b>(柔毛の中で、脂肪にもどる)</p>';

var NOTE='<p>ノートに、消化の表を書いてみましょう。何も見ずに、次の順で書けるようになることが目標です。</p>'+figNote()+
 SM+'※ 脂肪の2つ目の消化液は、胆汁です。胆汁は、酵素をふくみません。</p>'+
 '<p>書けたら、厳選ポイントの表と見くらべて、まちがいを直しましょう。</p>';

window.UNIT={
no:"2-14",title:"消化と吸収",
sections:[
{type:"text",point:true,title:"厳選ポイント",html:POINT},
{type:"problem",title:"問題",body:QBODY,
 parts:[{type:"tree",svg:fig1("blank"),answers:ANS,choices:CH}]},
{type:"answer",html:ANSW},
{type:"problem",title:"補充問題",body:SBODY,
 parts:[
  {label:"ブドウ糖",type:"choice",choices:["毛細血管","リンパ管"],accept:["毛細血管"]},
  {label:"アミノ酸",type:"choice",choices:["毛細血管","リンパ管"],accept:["毛細血管"]},
  {label:"脂肪酸など",type:"choice",choices:["毛細血管","リンパ管"],accept:["リンパ管"]}
 ],
 solution:SOL2},
{type:"text",title:"ノートに書いてみよう",html:NOTE}
]};
})();
